settings.custom_liquid:
{%- comment -%}
  Custom Liquid block — Bundle indhold
  Brug på selve bundleproduktets side.
  Bruger metafelt: custom.bundle_includes (list.product_reference)
  — sat automatisk via Cowork på alle bundle-produkter.
{%- endcomment -%}

{%- comment -%} ═══ KONFIGURATION — rediger her ═══ {%- endcomment -%}
{%- assign section_heading  = 'DETTE SÆT INDEHOLDER' -%}
{%- assign compare_label    = 'Købt separat' -%}
{%- assign bundle_label     = 'Sætpris' -%}
{%- assign savings_label    = 'Du sparer' -%}
{%- comment -%} ═══════════════════════════════════ {%- endcomment -%}

{%- liquid
  assign included_products = product.metafields.custom.bundle_includes.value
  assign current_variant   = product.selected_or_first_available_variant

  assign individual_total = 0
  if included_products != blank and included_products.size > 0
    for p in included_products
      assign pv = p.selected_or_first_available_variant
      assign individual_total = individual_total | plus: pv.price
    endfor
    assign bundle_price   = current_variant.price
    assign savings_amount = individual_total | minus: bundle_price
    if individual_total > 0
      assign savings_pct = savings_amount | times: 100 | divided_by: individual_total
    else
      assign savings_pct = 0
    endif
    assign show_section = true
  else
    assign show_section = false
  endif
-%}

{%- if show_section -%}

{%- assign uid = block.id | default: product.id -%}
<div class="yyc-wrap" id="yyc-{{ uid }}">

  <div class="yyc-heading">{{ section_heading }}</div>

  <div class="yyc-card">
    {%- if savings_pct > 0 -%}
    <span class="yyc-badge">−{{ savings_pct }}%</span>
    {%- endif -%}

    <ul class="yyc-list">
      {%- for p in included_products -%}
        {%- assign pv = p.selected_or_first_available_variant -%}
        <li class="yyc-item">
          <a href="{{ p.url }}" class="yyc-item__link">
            <div class="yyc-item__thumb"
              {%- if p.featured_image %} style="background-image:url('{{ p.featured_image | image_url: width: 104 }}')"{% endif %}></div>
            <div class="yyc-item__name">{{ p.title }}</div>
          </a>
          <span class="yyc-item__price">{{ pv.price | money }}</span>
        </li>
      {%- endfor -%}
    </ul>

    <div class="yyc-divider"></div>

    <div class="yyc-summary">
      {%- if savings_amount > 0 -%}
      <div class="yyc-summary__row yyc-summary__row--compare">
        <span>{{ compare_label }}</span>
        <span class="yyc-summary__strike">{{ individual_total | money }}</span>
      </div>
      {%- endif -%}
      <div class="yyc-summary__row yyc-summary__row--bundle">
        <span>{{ bundle_label }}</span>
        <span class="yyc-summary__bundle-price">{{ bundle_price | money }}</span>
      </div>
      {%- if savings_amount > 0 -%}
      <div class="yyc-summary__row yyc-summary__row--savings">
        <span>{{ savings_label }}</span>
        <span class="yyc-summary__savings">{{ savings_amount | money }}</span>
      </div>
      {%- endif -%}
    </div>
  </div>

</div>

<style>
  #yyc-{{ uid }} {
    --yy-green: #5b8a48;
    --yy-dark:  #1a1a1a;
    --yy-gray:  #6b6b6b;
    --yy-line:  #ececec;
    font-family: -apple-system, BlinkMacSystemFont, 'Inter', sans-serif;
    -webkit-font-smoothing: antialiased;
    color: var(--yy-dark);
  }
  #yyc-{{ uid }} *, #yyc-{{ uid }} *::before, #yyc-{{ uid }} *::after { box-sizing: border-box; }

  #yyc-{{ uid }} .yyc-heading {
    font-size: 11px; font-weight: 700; letter-spacing: 0.14em;
    color: var(--yy-gray); margin: 0 0 10px;
  }
  #yyc-{{ uid }} .yyc-card {
    position: relative;
    border: 1.5px solid var(--yy-dark);
    border-radius: 12px; padding: 16px; background: #fff;
  }
  #yyc-{{ uid }} .yyc-badge {
    position: absolute; top: 12px; right: 12px;
    background: var(--yy-green); color: #fff;
    font-size: 11px; font-weight: 700; letter-spacing: 0.06em;
    padding: 4px 9px; border-radius: 999px; line-height: 1;
  }
  #yyc-{{ uid }} .yyc-list { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 10px; }
  #yyc-{{ uid }} .yyc-item { display: flex; align-items: center; gap: 12px; }
  #yyc-{{ uid }} .yyc-item__link {
    display: flex; align-items: center; gap: 12px;
    flex: 1; min-width: 0; text-decoration: none; color: inherit;
  }
  #yyc-{{ uid }} .yyc-item__link:hover .yyc-item__name { text-decoration: underline; }
  #yyc-{{ uid }} .yyc-item__thumb {
    width: 48px; height: 48px; border-radius: 6px;
    background-color: #f0ede7; background-size: cover; background-position: center; flex-shrink: 0;
  }
  #yyc-{{ uid }} .yyc-item__name { font-size: 13px; font-weight: 500; line-height: 1.3; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  #yyc-{{ uid }} .yyc-item__price { font-size: 13px; font-weight: 600; white-space: nowrap; margin-left: auto; flex-shrink: 0; }
  #yyc-{{ uid }} .yyc-divider { border: none; border-top: 1px solid var(--yy-line); margin: 14px 0; }
  #yyc-{{ uid }} .yyc-summary { display: flex; flex-direction: column; gap: 6px; }
  #yyc-{{ uid }} .yyc-summary__row { display: flex; justify-content: space-between; align-items: center; font-size: 13px; }
  #yyc-{{ uid }} .yyc-summary__row--compare { color: var(--yy-gray); }
  #yyc-{{ uid }} .yyc-summary__strike { text-decoration: line-through; }
  #yyc-{{ uid }} .yyc-summary__row--bundle { font-weight: 700; }
  #yyc-{{ uid }} .yyc-summary__bundle-price { font-size: 20px; font-weight: 700; }
  #yyc-{{ uid }} .yyc-summary__row--savings { color: var(--yy-green); font-weight: 600; font-size: 12px; }
  #yyc-{{ uid }} .yyc-summary__savings { font-weight: 700; }
</style>

{%- endif -%}
